import React from "react";

export default function Logo({ size = 36, withWord = true, className = "" }) {
    return (
        <div className={`flex items-center ${className}`} data-testid="brand-logo">
            {withWord ? (
                <img 
                    src="/logo_dark.png" 
                    alt="Studio Form" 
                    style={{ height: size, width: "auto" }} 
                    className="block"
                />
            ) : (
                <div style={{ width: size, height: size, overflow: "hidden", position: "relative" }}>
                    <img 
                        src="/logo_dark.png" 
                        alt="Studio Form Mark" 
                        style={{ height: size, width: "auto", position: "absolute", left: 0, top: 0, maxWeight: "none" }} 
                        className="block"
                    />
                </div>
            )}
        </div>
    );
}
